const html = $input.first().json.body;
const text = html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
return [{ json: { text: text.substring(0, 10000), title: $input.first().json.title } }];

const resp = JSON.parse($input.first().json.content[0].text);
const items = Object.entries(resp).map(([key, value]) => ({
  json: {
    platform: key.includes('linkedin') ? 'linkedin' : key.includes('ig') ? 'instagram' : key.includes('fb') ? 'facebook' : key.includes('x_') ? 'twitter' : 'tiktok',
    format: key,
    text: value,
    source: 'content-multiplier',
    source_article: $input.first().json._parent.title
  }
}));
return items;
